import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import zlib from 'node:zlib';
import crypto from 'node:crypto';
import {tracking} from '../BP/scripts/core.js';
import {createTrackerDisplay,TRACKER_NAME} from '../BP/scripts/tracker-display.js';

const origin={x:0,y:64,z:0};
// Explicit world directions, not generated by the bearing formula under test.
const points={S:{x:0,y:64,z:100},SW:{x:-100,y:64,z:100},W:{x:-100,y:64,z:0},NW:{x:-100,y:64,z:-100},N:{x:0,y:64,z:-100},NE:{x:100,y:64,z:-100},E:{x:100,y:64,z:0},SE:{x:100,y:64,z:100}};

function decodePNG(data){
 assert.equal(data.subarray(0,8).toString('hex'),'89504e470d0a1a0a');
 let width,height,parts=[];
 for(let offset=8;offset<data.length;){const length=data.readUInt32BE(offset),kind=data.toString('ascii',offset+4,offset+8),payload=data.subarray(offset+8,offset+8+length);offset+=length+12;
  if(kind==='IHDR'){width=payload.readUInt32BE(0);height=payload.readUInt32BE(4);assert.equal(payload[8],8);assert.equal(payload[9],6);}
  if(kind==='IDAT')parts.push(payload);
 }
 const stride=width*4,raw=zlib.inflateSync(Buffer.concat(parts)),pixels=Buffer.alloc(width*height*4);assert.equal(raw.length,height*(1+stride));
 for(let y=0;y<height;y++)for(let x=0;x<stride;x++){
  const index=y*stride+x,filter=raw[y*(stride+1)],a=x<4?0:pixels[index-4],b=y?pixels[index-stride]:0,c=y&&x>=4?pixels[index-stride-4]:0;
  let prediction;
  switch(filter){
   case 0:prediction=0;break;
   case 1:prediction=a;break;
   case 2:prediction=b;break;
   case 3:prediction=Math.floor((a+b)/2);break;
   case 4:{const p=a+b-c,distances=[Math.abs(p-a),Math.abs(p-b),Math.abs(p-c)];prediction=[a,b,c][distances.indexOf(Math.min(...distances))];break;}
   default:assert.fail(`Unsupported PNG filter ${filter}`);
  }
  pixels[index]=(raw[y*(stride+1)+1+x]+prediction)&255;
 }
 return {width,height,pixels};
}
const sprite=frame=>decodePNG(fs.readFileSync(new URL(`../RP/textures/items/tracker_${frame}.png`,import.meta.url)));
const sha256=data=>crypto.createHash('sha256').update(data).digest('hex');
function redNeedle(frame){
 const {width,height,pixels}=sprite(frame);assert.equal(width,16);assert.equal(height,16);
 let xTotal=0,yTotal=0,count=0;
 for(let y=0;y<height;y++){
  for(let x=0;x<width;x++){const index=(y*width+x)*4,[r,g,b,a]=pixels.subarray(index,index+4);
   // The original dial is drawn in perspective, with its needle pivot at (8,7).
   // Its projected angle must not be treated as an unprojected circular angle.
   if(a>0&&r>160&&g<70&&b<90){xTotal+=x-8;yTotal+=y-7;count++;}
  }
 }
 assert(count>0,`Frame ${frame} has no red needle`);return {x:xTotal/count,y:yTotal/count};
}

test('south-facing hunter sees west on the right and east on the left in HUD and actual PNG',()=>{
 const right=tracking(origin,0,points.W),left=tracking(origin,0,points.E);
 assert.equal(right.arrow,'→');assert.equal(right.compassFrame,8);assert.equal(left.arrow,'←');assert.equal(left.compassFrame,24);
 const r=redNeedle(right.compassFrame),l=redNeedle(left.compassFrame);
 assert(r.x>1&&Math.abs(r.y)<0.5,'West is screen right when looking south: red needle must point right');
 assert(l.x< -1&&Math.abs(l.y)<0.5,'East is screen left when looking south: red needle must point left');
});

test('all eight explicit world bearings map to screen-relative arrows and sprite quadrants',()=>{
 const fixtures=[['S','↑',0,0,-1],['SW','↗',4,1,-1],['W','→',8,1,0],['NW','↘',12,1,1],['N','↓',16,0,1],['NE','↙',20,-1,1],['E','←',24,-1,0],['SE','↖',28,-1,-1]];
 for(const [direction,arrow,frame,sx,sy]of fixtures){const actual=tracking(origin,0,points[direction]),red=redNeedle(actual.compassFrame);
  assert.equal(actual.arrow,arrow,direction);assert.equal(actual.compassFrame,frame,direction);
  for(const [axis,sign]of [['x',sx],['y',sy]])if(sign===0)assert(Math.abs(red[axis])<0.5,`${direction} red ${axis} should be centered`);else assert(red[axis]*sign>0.25,`${direction} red ${axis} points to wrong side`);
 }
});

test('clockwise Bedrock yaw turns keep independent world-axis targets on the correct screen side',()=>{
 // Bedrock 0=south, +90=west, 180=north, -90=east. A right turn from
 // south faces west; therefore positive relative yaw must point screen right.
 for(const [yaw,front,right,left,back]of [[0,'S','W','E','N'],[90,'W','N','S','E'],[180,'N','E','W','S'],[-90,'E','S','N','W']]){
  for(const [direction,arrow,frame]of [[front,'↑',0],[right,'→',8],[left,'←',24],[back,'↓',16]]){
   const actual=tracking(origin,yaw,points[direction]);assert.equal(actual.arrow,arrow,`yaw ${yaw}, ${direction}`);assert.equal(actual.compassFrame,frame);
   const wrapped=tracking(origin,yaw+720,points[direction]);assert.equal(wrapped.compassFrame,frame);
  }
 }
});

test('32 quantized orientations are selected, including half-frame and wrap boundaries',()=>{
 const frames=new Set();for(let i=0;i<32;i++){const result=tracking(origin,-i*11.25,points.S);frames.add(result.compassFrame);assert.equal(result.compassFrame,i);}
 assert.equal(frames.size,32);
 for(const [yaw,frame]of [[-5.624,0],[-5.625,1],[-5.626,1],[5.624,0],[5.625,0],[5.626,31],[359.999,0],[-359.999,0]])assert.equal(tracking(origin,yaw,points.S).compassFrame,frame,`yaw ${yaw}`);
 for(let yaw=-720;yaw<720;yaw+=0.37){const frame=tracking(origin,yaw,points.S).compassFrame;const error=((frame*11.25+yaw+540)%360+360)%360-180;assert(Math.abs(error)<=5.6250001,`Angular quantization exceeded half a frame: ${error}`);}
});

test('all tracker sprites preserve every original Mojang RGBA pixel with the correct source-cell mapping',()=>{
 const data=fs.readFileSync(new URL('../tools/vendor/vanilla-compass/compass_atlas.png',import.meta.url));
 assert.equal(sha256(data),'7061f07c69c447f164d61fc009aaf4c9815ad854e59e6f17eea0a742583ed6f8','Use the reviewed and pinned upstream asset');
 const original=decodePNG(data);assert.equal(original.width,16);assert.equal(original.height,512);
 for(let frame=0;frame<32;frame++){
  const generated=sprite(frame),cell=(frame+16)%32;assert.equal(generated.width,16);assert.equal(generated.height,16);
  assert.deepEqual(generated.pixels,original.pixels.subarray(cell*1024,(cell+1)*1024),`Frame ${frame} must exactly preserve source cell ${cell}`);
 }
});

test('native 32-cell artwork preserves its 28 distinct images and original duplicate cells',()=>{
 const hashes=Array.from({length:32},(_,frame)=>sha256(sprite(frame).pixels));assert.equal(new Set(hashes).size,28);
 for(const same of [[23,25],[7,8,9],[11,12]])for(const frame of same)assert.equal(hashes[frame],hashes[same[0]],`Original repeated cell changed at frame ${frame}`);
});

test('third-party compass source hashes and license notices accompany the extracted sprites',()=>{
 const root=new URL('../tools/vendor/vanilla-compass/',import.meta.url),source=JSON.parse(fs.readFileSync(new URL('SOURCE.json',root),'utf8'));
 assert.equal(source.release,'v1.26.60.5');assert.equal(source.commit,'15701fa9c13923f12662984c32c124327e40e3d3');
 for(const entry of source.files){const bytes=fs.readFileSync(new URL(entry.file,root));assert.equal(bytes.length,entry.bytes);assert.equal(sha256(bytes),entry.sha256);assert(entry.url.includes(source.commit));}
 const notice=fs.readFileSync(new URL('NOTICE.md',root)),packNotice=fs.readFileSync(new URL('../RP/NOTICE.md',import.meta.url));assert.deepEqual(packNotice,notice);
 assert.match(notice.toString('utf8'),/excluded from Manhunt Night's MIT license/);assert.match(notice.toString('utf8'),/NOT AN OFFICIAL MINECRAFT PRODUCT/);
 assert.match(fs.readFileSync(new URL('../LICENSE',import.meta.url),'utf8'),/does not apply to Mojang's compass texture/);
});

function displayHarness(){
 const players=[];const display=createTrackerDisplay({inventory:p=>p.inventory,makeTracker:typeId=>({typeId,amount:1})});
 function player(id,yaw=0){const items=Array(36);const p={id,location:{...origin},yaw,selectedSlotIndex:0,reads:0,writes:0,items,getRotation(){return {x:0,y:this.yaw};}};
  p.inventory={size:36,getItem(slot){p.reads++;return items[slot];},setItem(slot,value){p.writes++;items[slot]=value;}};players.push(p);return p;
 }
 return {display,player,players};
}

test('inventory-change cache updates only known tracker slots without a full scan every tick',()=>{
 const {display,player}=displayHarness(),p=player('A');p.items[2]={typeId:'mh:tracker_0',amount:1};p.items[24]={typeId:'mh:tracker_0',amount:1};
 display.scan(p);assert.equal(p.reads,36);p.reads=0;display.update(p,points.S);assert.equal(p.reads,3,'Two cached slots and one selected-slot fallback');assert.equal(p.writes,0);
 p.items[5]={typeId:'mh:tracker_0',amount:1};display.changed({player:p,slot:5,itemStack:p.items[5]});p.reads=0;display.update(p,points.S);assert.equal(p.reads,4);
 p.items[2]=undefined;display.changed({player:p,slot:2,itemStack:undefined,beforeItemStack:{typeId:'mh:tracker_0'}});p.reads=0;display.update(p,points.S);assert.equal(p.reads,3);
 p.items[24]={typeId:'minecraft:diamond',amount:6};p.reads=0;display.update(p,points.W);assert.equal(p.reads,3);assert.equal(p.items[24].typeId,'minecraft:diamond');
 p.reads=0;display.update(p,points.W);assert.equal(p.reads,2,'Stale cached slot should be removed after detection');
 p.reads=0;display.changed({player:p,slot:5,itemStack:{typeId:'mh:tracker_8'},beforeItemStack:{typeId:'mh:tracker_0'}});assert.equal(p.reads,0,'Animation frame changes must not trigger inventory-wide reconciliation');
});

test('two owners retain independent frame state and unchanged angles do not rewrite stacks',()=>{
 const {display,player}=displayHarness(),a=player('A'),b=player('B',90);
 for(const p of [a,b]){p.items[3]={typeId:'mh:tracker_0',amount:1};display.scan(p);display.update(p,points.S);}
 assert.equal(a.items[3].typeId,'mh:tracker_0');assert.equal(b.items[3].typeId,'mh:tracker_24');assert.equal(b.items[3].nameTag,TRACKER_NAME);
 a.yaw=-90;display.update(a,points.S);assert.equal(a.items[3].typeId,'mh:tracker_8');assert.equal(b.items[3].typeId,'mh:tracker_24');
 const writes=a.writes;display.update(a,points.S);assert.equal(a.writes,writes);display.reset();a.reads=0;display.update(a,points.S);assert.equal(a.reads,38,'After reset one scan, selected-slot fallback and cached tracker read are expected');
});
